256:   resolverProyectosDesdeCalendario() {
257:     if (!this.calendarEventosPTD || this.calendarEventosPTD.length === 0) return;
258:     const proyectosMap = new Map<string, any>();
259:     this.calendarEventosPTD.forEach((evento: any) => {
260:       const id = String(evento.CodigoProyecto);
261:       if (id && evento.NombreProyecto && !proyectosMap.has(id)) {
262:         proyectosMap.set(id, { Id: id, Codigo: id, Nombre: evento.NombreProyecto });
263:       }
264:     });
265:     this.proyectos = Array.from(proyectosMap.values());
266:   }
